css:
.dvl-sim-container {
    padding: 28px;
    background: #faf8f3;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #1f2937;
    max-width: 1280px;
    margin: 0 auto;
}

.dvl-sim-container h1,
.dvl-sim-container h2,
.dvl-sim-container h3 {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
    letter-spacing: -0.01em;
}

.dvl-sim-header {
    background: #1a2744;
    color: #faf8f3;
    border-radius: 4px;
    padding: 32px 36px;
    margin-bottom: 24px;
    border-left: 6px solid #5ec962;
    position: relative;
}

.dvl-sim-firm {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: #5ec962;
    margin-bottom: 8px;
    font-weight: 600;
}

.dvl-sim-header h1 {
    color: #faf8f3;
    margin: 0;
    font-size: 1.9rem;
    font-weight: 700;
    line-height: 1.15;
}

.dvl-sim-subtitle {
    color: #cbd5e1;
    font-size: 0.95rem;
    margin-top: 8px;
    font-style: italic;
}

.dvl-sim-meta {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 4px;
    padding: 10px 18px;
    display: inline-block;
    margin-bottom: 22px;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #4b5563;
    font-weight: 600;
}

.dvl-sim-meta #currentDay,
.dvl-sim-meta #maxPeriods {
    color: #1a2744;
    font-weight: 700;
}

.dvl-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}

.dvl-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 4px;
    padding: 22px 22px 20px;
    border-top: 3px solid #1a2744;
    transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.dvl-sim-kpi-card:hover {
    box-shadow: 0 4px 14px rgba(26,39,68,0.08);
    transform: translateY(-2px);
}

.dvl-kpi-score   { border-top-color: #21918c; }
.dvl-kpi-last    { border-top-color: #3b528b; }
.dvl-kpi-cfo     { border-top-color: #5ec962; }
.dvl-kpi-pct     { border-top-color: #fde725; }

.dvl-sim-kpi-label {
    color: #6b7280;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
    font-weight: 600;
}

.dvl-sim-kpi-value {
    font-size: 2.1rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1;
    margin-bottom: 6px;
    font-variant-numeric: tabular-nums;
}

.dvl-sim-kpi-sub {
    color: #6b7280;
    font-size: 0.78rem;
}

.dvl-sim-briefing {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-left: 4px solid #21918c;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
}

.dvl-sim-briefing-eyebrow {
    color: #177f7a;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    font-weight: 700;
    margin-bottom: 6px;
}

.dvl-sim-briefing h2 {
    margin: 0 0 16px 0;
    font-size: 1.2rem;
    font-weight: 700;
}

.dvl-sim-briefing-row {
    display: grid;
    grid-template-columns: 140px 1fr;
    gap: 14px;
    padding: 8px 0;
    border-top: 1px solid #f1f5f9;
    font-size: 0.92rem;
    line-height: 1.5;
}

.dvl-sim-briefing-row:first-of-type {
    border-top: none;
}

.dvl-sim-briefing-label {
    color: #6b7280;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    padding-top: 2px;
}

.dvl-sim-controls {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 4px;
    padding: 26px 28px;
    margin-bottom: 24px;
}

.dvl-sim-controls h3 {
    margin: 0 0 18px 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #1a2744;
}

.dvl-sim-decision-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 16px 22px;
    margin-bottom: 22px;
}

.dvl-sim-decision label {
    display: block;
    color: #1a2744;
    font-size: 0.82rem;
    font-weight: 600;
    margin-bottom: 6px;
    letter-spacing: 0.01em;
}

.dvl-sim-controls select {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    color: #1a2744;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.dvl-sim-controls select:focus {
    outline: none;
    border-color: #21918c;
    box-shadow: 0 0 0 3px rgba(33,145,140,0.15);
}

.dvl-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}

.dvl-sim-action-row {
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
}

.dvl-sim-controls .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    color: #faf8f3;
    border-radius: 4px;
    padding: 10px 22px;
    font-size: 0.9rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.dvl-sim-controls .btn-primary:hover {
    background: #21918c;
    border-color: #21918c;
}

.dvl-sim-controls .btn-outline-secondary {
    border-radius: 4px;
    border-color: #cbd5e1;
    color: #4b5563;
    background: transparent;
    font-size: 0.82rem;
}

.dvl-sim-controls .btn-outline-secondary:hover {
    background: #f1f5f9;
    color: #1a2744;
    border-color: #94a3b8;
}

.dvl-sim-history-card,
.dvl-sim-chart-card {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 4px;
    padding: 22px 26px;
    margin-bottom: 22px;
}

.dvl-sim-history-card h3,
.dvl-sim-chart-card h3 {
    margin: 0 0 14px 0;
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}

.dvl-sim-history-card .table {
    margin: 0;
    font-size: 0.88rem;
    color: #1f2937;
}

.dvl-sim-history-card .table thead th {
    border-top: none;
    border-bottom: 2px solid #1a2744;
    color: #1a2744;
    font-weight: 700;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 10px 8px;
}

.dvl-sim-history-card .table tbody td {
    padding: 10px 8px;
    border-top: 1px solid #f1f5f9;
    font-variant-numeric: tabular-nums;
}

.dvl-sim-chart-wrap {
    height: 320px;
    position: relative;
}

@media (max-width: 768px) {
    .dvl-sim-container { padding: 16px; }
    .dvl-sim-header { padding: 22px 20px; }
    .dvl-sim-header h1 { font-size: 1.4rem; }
    .dvl-sim-decision-grid { grid-template-columns: 1fr; }
    .dvl-sim-briefing-row { grid-template-columns: 1fr; }
    .dvl-sim-briefing-label { padding-bottom: 2px; }
    .dvl-sim-kpi-value { font-size: 1.6rem; }
}


/* a11y: visible keyboard focus on every interactive control */
.dvl-sim-container select:focus-visible,
.dvl-sim-container input:focus-visible,
.dvl-sim-container button:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
}

.dvl-sim-complete {
    margin: 18px 0 24px 0;
    padding: 20px 24px;
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-left: 4px solid #177f7a;
    border-radius: 4px;
    color: #1f2937;
}
.dvl-sim-complete h3 { margin: 0 0 6px 0; color: #1a2744; }
.dvl-sim-complete-band { margin: 0 0 10px 0; font-weight: 600; color: #177f7a; }
.dvl-sim-done-score { font-weight: 700; font-size: 1.2rem; color: #1a2744; }

@media (prefers-reduced-motion: reduce) {
    .dvl-sim-container *,
    .dvl-sim-container *::before,
    .dvl-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

