    var DIMS = ['chart_type', 'data_ink', 'encoding', 'palette', 'axis', 'labelling'];
    var SELECT_IDS = {
        chart_type: 'chartTypeSelect',
        data_ink:   'dataInkSelect',
        encoding:   'encodingSelect',
        palette:    'paletteSelect',
        axis:       'axisSelect',
        labelling:  'labellingSelect'
    };

    class DVLAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Data Visualisation Lab';
            this.version = '1.1.0';
            this.CASES = CASES;
        }
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    maxScore: 0,
                    cfoMood: 'skeptical',
                    scoreHistory: [],
                    maxScoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    chart_type: '',
                    data_ink: '',
                    encoding: '',
                    palette: '',
                    axis: '',
                    labelling: ''
                };
            }
            this._renderedCase = null;
            var self = this;
            setTimeout(function() {
                self._updateBriefing(state);
                self._syncControlsFromDecisions(state);
            }, 120);
        }

        _syncControlsFromDecisions(state) {
            var dec = (state && state.decisions) || {};
            DIMS.forEach(function(dim) {
                var v = dec[dim];
                if (v === undefined || v === null || v === '') return;
                var sel = document.getElementById(SELECT_IDS[dim]);
                if (sel) sel.value = String(v);
            });
        }

        _lang() {
            // window.mySimulation.language is the framework property. .currentLanguage
            // does not exist and reads undefined, silently falling back to English.
            var l = (window.mySimulation && window.mySimulation.language) || 'en';
            return String(l).split('-')[0].toLowerCase();
        }

        _t(key, fallback) {
            try {
                var v = window.mySimulation.t(key);
                if (v && v !== key) return v;
            } catch (e) {}
            return fallback;
        }
        _updateBriefing(state) {
            var sim = window.mySimulation;
            if (!sim || !sim.t) return;
            var t = sim.t.bind(sim);
            var total = this.CASES.length;
            var period = (state && state.currentPeriod) || 1;
            var controls = document.getElementById('decisionControls');
            var done = document.getElementById('runCompletePanel');

            if (period > total) {
                // Terminal state. The previous version clamped the index and left all six
                // selects and Submit live on case 5 forever.
                if (controls) controls.style.display = 'none';
                if (done) {
                    done.style.display = 'block';
                    var ds = (state && state.domainState) || {};
                    done.innerHTML = '<h3>' + this._t('done_title', 'Lab complete') + '</h3>'
                        + '<p>' + this._t('done_body', 'All five redesigns are submitted. Your visual-argument habits are on the record.') + '</p>'
                        + '<p class="dvl-sim-done-score">' + (ds.totalScore || 0)
                        + ' / ' + (ds.maxScore || 0) + '</p>';
                }
                var titleDone = document.getElementById('caseTitle');
                if (titleDone) titleDone.textContent = this._t('done_title', 'Lab complete');
                return;
            }

            if (controls) controls.style.display = '';
            if (done) done.style.display = 'none';

            var idx = Math.min(period - 1, total - 1);
            var c = this.CASES[idx];

            var titleEl = document.getElementById('caseTitle');
            if (titleEl) titleEl.innerHTML = t(c.titleKey);

            var taskEl = document.getElementById('caseTask');
            if (taskEl) taskEl.innerHTML = t(c.taskKey);

            var origEl = document.getElementById('caseOriginal');
            if (origEl) origEl.innerHTML = t(c.originalKey);

            var failEl = document.getElementById('caseFailure');
            if (failEl) failEl.innerHTML = t(c.failureKey);

            var key = idx + ':' + this._lang();
            if (this._renderedCase === key) return;

            // Rebuild the six selects only on a genuine case or language change. Rebuilding
            // them on every call is what made this simulation impossible to complete: the
            // rebuild ended with sel.value = '' and validateDecisions read straight after.
            DIMS.forEach(function(dim) {
                var sel = document.getElementById(SELECT_IDS[dim]);
                if (!sel) return;
                sel.innerHTML = '';
                var ph = document.createElement('option');
                ph.value = '';
                ph.textContent = t('select_placeholder');
                sel.appendChild(ph);
                c.options[dim].forEach(function(opt) {
                    var o = document.createElement('option');
                    o.value = opt.value;
                    o.textContent = t(opt.tk);
                    sel.appendChild(o);
                });
                sel.value = '';
            });
            this._renderedCase = key;
        }
        validateDecisions(decisions) {
            // Read the six selects FIRST. The previous version re-rendered the briefing
            // here, which rebuilds every select and resets it to the empty placeholder,
            // so these reads always returned '' and the guard below rejected every
            // submit. The simulation could not be completed at all.
            var ok = true;
            var sim = window.mySimulation;
            DIMS.forEach(function(dim) {
                var sel = document.getElementById(SELECT_IDS[dim]);
                if (sel) decisions[dim] = sel.value;
                if (!decisions[dim]) ok = false;
            });
            if (!ok) {
                sim.uiManager.showNotification(sim.t('missing_decisions'), 'warning');
                return false;
            }
            return true;
        }


        calculateResults(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.CASES.length - 1);
            var c = this.CASES[idx];
            var dimScores = {};
            var totalThisRound = 0;
            var maxThisRound = 0;

            DIMS.forEach(function(dim) {
                var picked = state.decisions[dim];
                var opts = c.options[dim];
                var score = 0;
                var maxOpt = 0;
                opts.forEach(function(o) {
                    if (o.value === picked) score = o.score;
                    if (o.score > maxOpt) maxOpt = o.score;
                });
                dimScores[dim] = score;
                totalThisRound += score;
                maxThisRound += maxOpt;
            });

            state.domainState.totalScore += totalThisRound;
            state.domainState.maxScore += maxThisRound;
            state.domainState.scoreHistory.push(totalThisRound);
            state.domainState.maxScoreHistory.push(maxThisRound);

            var pct = state.domainState.maxScore > 0
                ? state.domainState.totalScore / state.domainState.maxScore : 0;
            // platform score: running percent of attainable points, the same overallScore that getPerformanceSummary reports
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(pct * 100))) });
            var mood = 'skeptical';
            if (pct >= 0.85)      mood = 'convinced';
            else if (pct >= 0.7)  mood = 'impressed';
            else if (pct >= 0.55) mood = 'pleased';
            else if (pct >= 0.4)  mood = 'curious';
            state.domainState.cfoMood = mood;

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing(Object.assign({}, (window.mySimulation && window.mySimulation.state) || state, { currentPeriod: __eqilNext }));
            })((state.currentPeriod || 1) + 1), 500);

            return {
                period: state.currentPeriod,
                caseTitleKey: c.titleKey,
                pick_chart_type: state.decisions.chart_type,
                pick_data_ink:   state.decisions.data_ink,
                pick_encoding:   state.decisions.encoding,
                pick_palette:    state.decisions.palette,
                pick_axis:       state.decisions.axis,
                pick_labelling:  state.decisions.labelling,
                score_chart_type: dimScores.chart_type,
                score_data_ink:   dimScores.data_ink,
                score_encoding:   dimScores.encoding,
                score_palette:    dimScores.palette,
                score_axis:       dimScores.axis,
                score_labelling:  dimScores.labelling,
                roundScore: totalThisRound,
                roundMax:   maxThisRound,
                cumulativeScore: state.domainState.totalScore,
                cumulativeMax:   state.domainState.maxScore,
                pct: Math.round(pct * 100),
                mood: mood
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');

            uiManager.bind('totalScoreDisplay', 'domainState.totalScore', function(v) {
                var sim = window.mySimulation;
                var m = (sim && sim.state && sim.state.domainState && sim.state.domainState.maxScore) || 0;
                return v + ' / ' + m;
            });
            uiManager.bind('lastScoreDisplay', 'results.roundScore', function(v) {
                if (v === undefined || v === null) return '—';
                var sim = window.mySimulation;
                var m = (sim && sim.state && sim.state.results && sim.state.results.roundMax) || 18;
                return v + ' / ' + m;
            });
            uiManager.bind('cfoDisplay', 'domainState.cfoMood', function(v) {
                if (!v) return '—';
                return window.mySimulation.t('mood_' + v);
            });
            uiManager.bind('pctDisplay', 'domainState.totalScore', function(v) {
                var sim = window.mySimulation;
                var m = (sim && sim.state && sim.state.domainState && sim.state.domainState.maxScore) || 0;
                if (m === 0) return '—';
                return Math.round((v / m) * 100) + '%';
            });
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Score',
                                data: [],
