                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { display: true, position: 'bottom', labels: { color: '#1a2744' } },
                            tooltip: { backgroundColor: '#1a2744' }
                        },
                        scales: {
                            x: { grid: { display: false }, ticks: { color: '#4b5563' } },
                            y: { beginAtZero: true, suggestedMax: 18, grid: { color: '#f1f5f9' }, ticks: { color: '#4b5563' } }
                        }
                    }
                }
            };
        }
        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var scores = ds.scoreHistory || [];
            var label = this._t('chart_case_label', 'Case');
            var labels = scores.map(function(_, i) { return label + ' ' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: scores },
                        { data: ds.maxScoreHistory || [] }
                    ]
                }
            };
        }


        getHint(state, results) {
            if (!results) return null;
            var pct = results.roundMax ? results.roundScore / results.roundMax : 0;
            var caseId = results.period;
            if (pct >= 0.9)  return window.mySimulation.t('hint_excellent_c' + caseId);
            if (pct >= 0.7)  return window.mySimulation.t('hint_good_c' + caseId);
            if (pct >= 0.45) return window.mySimulation.t('hint_mid_c' + caseId);
            return window.mySimulation.t('hint_poor_c' + caseId);
        }

        getHistoryTableConfig() {
            return [
                { key: 'period',           label: 'Case',  i18nKey: 'col_case' },
                { key: 'score_chart_type', label: 'Type',  i18nKey: 'col_type',  formatter: function(v) { return v + '/3'; } },
                { key: 'score_data_ink',   label: 'Ink',   i18nKey: 'col_ink',   formatter: function(v) { return v + '/3'; } },
                { key: 'score_encoding',   label: 'Enc',   i18nKey: 'col_enc',   formatter: function(v) { return v + '/3'; } },
                { key: 'score_palette',    label: 'Color', i18nKey: 'col_color', formatter: function(v) { return v + '/3'; } },
                { key: 'score_axis',       label: 'Axis',  i18nKey: 'col_axis',  formatter: function(v) { return v + '/3'; } },
                { key: 'score_labelling',  label: 'Label', i18nKey: 'col_label', formatter: function(v) { return v + '/3'; } },
                { key: 'roundScore',       label: 'Total', i18nKey: 'col_total', formatter: function(v) { return v + ' / 18'; } }
            ];
        }
        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var total = 0;
            var max = 0;
            history.forEach(function(h) {
                total += (h.results && h.results.roundScore) || 0;
                max += (h.results && h.results.roundMax) || 18;
            });
            var pct = max ? total / max : 0;
            var overall = Math.round(pct * 100);

            // performance is a stable id; performanceLabel carries the localized text.
            var perf = 'beginner';
            if (pct >= 0.85)      perf = 'tufte';
            else if (pct >= 0.7)  perf = 'strong';
            else if (pct >= 0.55) perf = 'developing';

            var labels = {
                beginner: this._t('perf_beginner', 'Beginner'),
                developing: this._t('perf_developing', 'Developing'),
                strong: this._t('perf_strong', 'Strong'),
                tufte: this._t('perf_tufte', 'Tufte-grade')
            };

            var insights = [];
            if (pct >= 0.85)      insights.push(this._t('summary_insight_excellent', ''));
            else if (pct >= 0.7)  insights.push(this._t('summary_insight_strong', ''));
            else if (pct >= 0.55) insights.push(this._t('summary_insight_developing', ''));
            else                  insights.push(this._t('summary_insight_beginner', ''));
            insights.push(this._t('summary_insight_close', ''));

            return {
                totalScore: total,
                maxScore: max,
                percent: overall,
                overallScore: overall,
                score: overall,
                composite: overall,
                performance: perf,
                performanceKey: perf,
                performanceLabel: labels[perf],
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var parts = [];
            parts.push('<div class="dvl-sim-complete">');
            parts.push('<h3>' + this._t('done_title', 'Lab complete') + '</h3>');
            parts.push('<p class="dvl-sim-complete-band">' + (s.performanceLabel || '')
                + ' &middot; ' + (s.overallScore || 0) + '/100</p>');
            parts.push('<p>' + (s.totalScore || 0) + ' / ' + (s.maxScore || 0) + '</p>');
            (s.insights || []).forEach(function(i) { if (i) parts.push('<p>' + i + '</p>'); });
            parts.push('</div>');
            return parts.join('');
        }


